'use strict';
const projectBoardStatuses={'in-progress':'In progress',unpublished:'Unpublished',finished:'Finished'};
let projectBoardEntries=[],projectOpenTabs=[],activeBoardProjectId=null,projectBoardSwitching=false,projectBoardWrites=Promise.resolve();
const projectBoardSessions=new Map();
$('projectDialog').querySelector('h2').textContent='Your video projects';$('projectDialog').querySelector('p').textContent='Keep several projects underway. Open tabs let you switch between drafts; each project keeps its own media and editing history.';
$('projectList').before(Object.assign(document.createElement('div'),{className:'project-board-tools',innerHTML:'<input id="projectBoardSearch" placeholder="Search projects…" aria-label="Search saved projects"><select id="projectBoardFilter" aria-label="Project status"><option value="all">All projects</option><option value="in-progress">In progress</option><option value="unpublished">Unpublished</option><option value="finished">Finished</option></select>'}));
$('projectList').classList.add('project-board');document.querySelector('.stagebar').before(Object.assign(document.createElement('nav'),{id:'projectWorkspaceTabs',className:'project-workspace-tabs',hidden:true}));
function boardEditorState(){return{sceneIndex,time,selected,selectedAudio}}
function boardBlocked(){return projectBoardSwitching||recording||audioBusy||speechProcessing||storyProcessing||videoImportBusy||motionTake||typeof exportQueueRunning!=='undefined'&&exportQueueRunning}
function boardPoster(){try{const source=document.createElement('canvas');source.width=480;source.height=270;renderSceneFrame(source.getContext('2d'),current(),time);return source.toDataURL('image/jpeg',.65)}catch{return''}}
function queueProjectBoardWrite(snapshot,{status,editor,poster}={}){const work=async()=>{const previous=await projectRecords('readonly',s=>s.get(snapshot.projectId)),entry={...previous,id:snapshot.projectId,project:structuredClone(snapshot),status:status||previous?.status||'in-progress',updatedAt:Date.now(),editor:editor||previous?.editor,poster:poster??previous?.poster??''};await projectRecords('readwrite',s=>s.put(entry,entry.id));const i=projectBoardEntries.findIndex(e=>e.id===entry.id);if(i<0)projectBoardEntries.push(entry);else projectBoardEntries[i]=entry;return entry};const promise=projectBoardWrites.then(work,work);projectBoardWrites=promise.catch(()=>{});return promise}
async function saveBoardProject(){if(projectBoardSwitching)throw Error('Wait for the project switch to finish.');project.projectId??=uid();activeBoardProjectId=project.projectId;save();const entry=await queueProjectBoardWrite(structuredClone(project),{editor:boardEditorState(),poster:boardPoster()});projectOpenTabs=[...projectOpenTabs.filter(id=>id!==entry.id),entry.id].slice(-8);await workspacePut('projectOpenTabs',projectOpenTabs);renderProjectWorkspaceTabs();return entry}
const storeBeforeProjectBoard=storeWorkspace;storeWorkspace=async function(snapshot){await storeBeforeProjectBoard(snapshot);if(!projectBoardSwitching&&snapshot.projectId&&snapshot.projectId===activeBoardProjectId&&!(typeof exportQueueRunning!=='undefined'&&exportQueueRunning))await queueProjectBoardWrite(snapshot,{editor:boardEditorState()})};
async function switchBoardProject(id){if(boardBlocked())return toast('Finish the current media task before switching projects.');if(id===activeBoardProjectId)return $('projectDialog').close();projectBoardSwitching=true;window.editorTaskBusy=true;stop();try{const existing=await projectRecords('readonly',s=>s.get(id));if(!existing?.project||!valid(existing.project))throw Error('This saved project is incomplete. Open a project backup.');if(project.projectId){const currentId=project.projectId;projectBoardSessions.set(currentId,{editor:boardEditorState(),history:historyStack.slice(),future:futureStack.slice()});await queueProjectBoardWrite(structuredClone(project),{editor:boardEditorState(),poster:boardPoster()})}else{project.projectId=uid();await queueProjectBoardWrite(structuredClone(project),{editor:boardEditorState(),poster:boardPoster()});projectOpenTabs.push(project.projectId)}const next=structuredClone(existing.project);next.projectId=id;activeBoardProjectId=id;loadProject(next);const session=projectBoardSessions.get(id),view=session?.editor||existing.editor;await hydrateAudio();if(view){sceneIndex=clamp(view.sceneIndex||0,0,project.scenes.length-1);time=clamp(view.time||0,0,current().duration);selected=current().objects.some(o=>o.id===view.selected)?view.selected:null;selectedAudio=tracks().some(c=>c.id===view.selectedAudio)?view.selectedAudio:null;selectLayers(selected?[selected]:[])}if(session){historyStack=session.history;futureStack=session.future}if(!projectOpenTabs.includes(id))projectOpenTabs.push(id);projectOpenTabs=[...new Set(projectOpenTabs)].slice(-8);await workspacePut('projectOpenTabs',projectOpenTabs);await storeBeforeProjectBoard(project);render();renderProjectWorkspaceTabs();$('projectDialog').close();toast('Project opened. Other drafts remain saved.')}catch(e){toast(e.message)}finally{projectBoardSwitching=false;window.editorTaskBusy=false}}
async function newBoardProject(){if(boardBlocked())return toast('Finish the current media task first.');try{await saveBoardProject();const oldId=project.projectId;projectBoardSessions.set(oldId,{editor:boardEditorState(),history:historyStack.slice(),future:futureStack.slice()});loadProject({version:1,projectId:uid(),title:'Untitled video',cast:[{id:uid(),...baseChar}],scenes:[scene('Scene 1')],audioClips:[]});activeBoardProjectId=project.projectId;await saveBoardProject();$('projectDialog').close();renderProjectWorkspaceTabs()}catch(e){toast('Could not save the current draft: '+e.message)}}
function renderProjectWorkspaceTabs(){const tabs=$('projectWorkspaceTabs');tabs.replaceChildren();const available=projectOpenTabs.filter(id=>projectBoardEntries.some(e=>e.id===id));tabs.hidden=available.length<2;for(const id of available){const entry=projectBoardEntries.find(e=>e.id===id),row=document.createElement('div');row.className='project-workspace-tab'+(activeBoardProjectId===id?' active':'');const b=storyButton(activeBoardProjectId===id?project.title:entry.project.title,()=>switchBoardProject(id));b.title=entry.project.title;b.dataset.projectTab=id;const close=storyButton('×',async()=>{if(boardBlocked())return;if(id===activeBoardProjectId){if(available.length===1)return;await saveBoardProject();const next=available.find(a=>a!==id);await switchBoardProject(next)}projectOpenTabs=projectOpenTabs.filter(a=>a!==id);await workspacePut('projectOpenTabs',projectOpenTabs);renderProjectWorkspaceTabs()},'Close project tab; keep its saved draft');close.disabled=id===activeBoardProjectId&&available.length===1;row.append(b,close);tabs.append(row)}}
renderProjects=async function(){try{await projectBoardWrites;projectBoardEntries=(await projectRecords('readonly',s=>s.getAll())).filter(e=>e?.project);const query=$('projectBoardSearch').value.trim().toLowerCase(),filter=$('projectBoardFilter').value,list=$('projectList');list.replaceChildren();for(const [status,name]of Object.entries(projectBoardStatuses)){if(filter!=='all'&&filter!==status)continue;const entries=projectBoardEntries.filter(e=>(e.status||'in-progress')===status&&e.project.title.toLowerCase().includes(query)).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)),column=document.createElement('section');column.className='project-board-column';column.dataset.projectStatus=status;const title=document.createElement('h3');title.textContent=name+' · '+entries.length;column.append(title);for(const entry of entries){const card=document.createElement('article');card.className='project-board-card';card.dataset.projectId=entry.id;if(entry.poster){const image=document.createElement('img');image.src=entry.poster;image.alt='';card.append(image)}const heading=document.createElement('strong');heading.textContent=entry.project.title;const info=document.createElement('p');info.textContent=entry.project.scenes.length+' scenes · '+entry.project.scenes.reduce((n,s)=>n+s.duration,0).toFixed(1)+'s'+(entry.id===activeBoardProjectId?' · open now':'');const state=storySelect(Object.entries(projectBoardStatuses),entry.status||'in-progress',async value=>{try{await projectBoardWrites;const saved=await projectRecords('readonly',s=>s.get(entry.id));saved.status=value;await projectRecords('readwrite',s=>s.put(saved,saved.id));await renderProjects()}catch{toast('Could not change the project status.')}},'Status for '+entry.project.title);const actions=document.createElement('div');actions.className='rig-tools';actions.append(storyButton('Open',()=>switchBoardProject(entry.id)),storyButton('Backup',()=>download(new Blob([JSON.stringify(entry.project)],{type:'application/json'}),entry.project.title+'.json')),storyButton('Delete',async()=>{if(boardBlocked())return;if(!confirm('Delete this saved project? The current editing workspace remains available.'))return;if(entry.id===activeBoardProjectId){activeBoardProjectId=null;delete project.projectId;clearTimeout(saveTimer)}await projectBoardWrites;await projectRecords('readwrite',s=>s.delete(entry.id));projectOpenTabs=projectOpenTabs.filter(id=>id!==entry.id);projectBoardSessions.delete(entry.id);await workspacePut('projectOpenTabs',projectOpenTabs);await renderProjects()}));card.append(heading,info,state,actions);column.append(card)}if(!entries.length){const empty=document.createElement('p');empty.className='note';empty.textContent='No '+name.toLowerCase()+' projects here yet.';column.append(empty)}list.append(column)}renderProjectWorkspaceTabs()}catch(e){toast('Could not load the project board: '+e.message)}};
$('saveProject').onclick=async()=>{try{await saveBoardProject();await renderProjects();toast('Draft saved with its media.')}catch(e){toast('Could not save this draft: '+e.message)}};$('newProject').onclick=newBoardProject;$('projectBoardSearch').oninput=renderProjects;$('projectBoardFilter').onchange=renderProjects;
const loadBeforeProjectBoard=loadProject;loadProject=function(p){if(!projectBoardSwitching)activeBoardProjectId=projectBoardEntries.some(e=>e.id===p.projectId)?p.projectId:null;loadBeforeProjectBoard(p);renderProjectWorkspaceTabs()};
const extrasBeforeProjectBoard=renderExtras;renderExtras=function(){extrasBeforeProjectBoard();renderProjectWorkspaceTabs()};
const projectBoardReady=Promise.all([workspaceValue('projectOpenTabs'),projectRecords('readonly',s=>s.getAll())]).then(([tabs,entries])=>{projectBoardEntries=entries.filter(e=>e?.project);projectOpenTabs=Array.isArray(tabs)?tabs.filter(id=>projectBoardEntries.some(e=>e.id===id)).slice(-8):[];if(project.projectId&&projectBoardEntries.some(e=>e.id===project.projectId)){activeBoardProjectId=project.projectId;if(!projectOpenTabs.includes(activeBoardProjectId))projectOpenTabs.push(activeBoardProjectId)}renderProjectWorkspaceTabs()}).catch(()=>{});
